action.mutation:
mutation DeleteMaintenanceCompletion($payload: [MaintenanceCompletionDeletePayloadInput!]!) {
        mutation: deleteMaintenanceCompletion(payload: $payload) { 
          id
          number
      }
    }

updateAction.mutation:
mutation createUpdateMaintenanceCompletion($create: [MaintenanceCompletionCreatePayloadInput!]!,$update: [MaintenanceCompletionUpdatePayloadInput!]!) {
          create: createMaintenanceCompletion(payload: $create) {
            id
            number
          }
          update: updateMaintenanceCompletion(payload: $update) {
            id
            number
          }
        }

options.__transform:
[$query({
  "api": $lowercase(data.api),
  "statement":'query Model($type: String!) {
    modelMap(where: { name: { _eq: $type }})
  }',
  "variables":{
    "type": data.model & "Document"
  }
}).modelMap.*.fields.{
  "id": name,
  "label": $startCase(name)
}[id != 'createdAt' 
  and id != "createdByUserId"
  and id != "updatedAt"
  and id != "updatedByUserId"
]]

dataTransform.transform:
(
  $EXCLUDED_KEYS := [
    "_id",
    "createdAt",
    "createdByUserId",
    "updatedAt",
    "updatedByUserId"
  ];

  $api := $coalesce([$variables.api, api]);
  $model := $coalesce([$variables.model, model]);

  $modelFields := $indexBy(
    $query({
      "api": $lowercase($api),
      "statement":'query Model($type: String!) {
        modelMap(where: { name: { _eq: $type }})
      }',
      "variables":{
        "type": $model & "Document"
      }
    }).modelMap.*.fields,
    function($field) {
      $field.name
    }
  );

  $isType := function($field, $type) {
    $field.type = $type or $field.type = $type & "!"
  };

  $formatData := function($fieldName, $record) {(
    $value := $lookup($record, $fieldName);
    $field := $lookup($modelFields, $fieldName);

    $isType($field, 'Date') ?
      $moment($value).format("L") :
    $isType($field, 'Time') ?
      $moment($value).format("LT") :
    $isType($field, 'DateTime') ?
      $moment($value).format("L LT") :
    $isType($field, 'JSON') or $isType($field, 'JSONObject') ?
      $jsonStringify($value, { "space": 2 }) :
    $isType($field, 'Boolean') ?
      ($value = true ? '\u2714' : $value = false ? '\u2716' : $value) :
    $isType($field, 'Address') ?
      $value.city & ", " & $value.state & " " & $value.country :
    $isType($field, 'Measure') ?
      $value.value & " " & $value.unit.code :
    $isType($field, 'RatioMeasure') ?
      $value.value & " " & $value.numeratorUnit.code & "/" & $value.denominatorUnit.code :
      $value
  )};

  $nodes := $flatten($map(edges.node, function($node) {
    (
      $keys := [
        $uniq(
          $append(
            $append(
              $keys($node.difference.added), 
              $keys($node.difference.deleted)
            ),
            $keys($node.difference.updated)
          )
        )[$isNil($findFirst($EXCLUDED_KEYS, function($v) { $v = $ }))]
      ];

      $append(
        $merge([
          $node,
          {
            "groupData": "",
            "groupChangedByUser": $node.changedByUser,
            "hierarchy": [$node.id]
          }
        ]),
        $keys.(
          $merge([$node, {
            "before": null,
            "after": null,
            "difference": null,
            "fieldBefore": null,
            "fieldAfter": null
          }, {
            "id": $node.id & "-" & $,
            "changeId": $node.id,
            "field": $startCase($),
            "fieldBefore": $formatData($, $node.before),
            "fieldAfter": $formatData($, $node.after)
          }]) ~> | $ | {
            "hierarchy": [changeId, id]
          } |
        )
      )
    )
  }));

  {
    "total": $count($nodes),
    "edges": $nodes.{
      "node": $
    }
  }
)
